app.innerHTML = "<!DOCTYPE html>\n<html lang=\"bn\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <title>GRE বই ২০২৪: সেরা GRE প্রস্তুতির বইসমূহ</title>\n\n  <!-- Bengali-friendly font -->\n  <link href=\"https://fonts.googleapis.com/css2?family=Noto+Sans+Bengali:wght@400;600;700;800&display=swap\" rel=\"stylesheet\">\n  <link rel=\"stylesheet\" href=\"styles.css\" />\n</head>\n<body>\n  <main class=\"wrap\">\n    <div class=\"grid\">\n      <!-- ================= LEFT COLUMN ================= -->\n      <div class=\"grid-left\">\n\n        <!-- Main article -->\n        <article class=\"article-card\" aria-labelledby=\"post-title\">\n          <nav class=\"crumbs\" aria-label=\"breadcrumb\">\n            <a href=\"#\">বিদেশে উচ্চশিক্ষা</a> /\n            <a href=\"#\">পরীক্ষাসমূহ</a> /\n            <a href=\"#\">GRE</a> /\n            <span aria-current=\"page\">বইসমূহ</span>\n          </nav>\n\n          <header class=\"post-head\">\n            <h1 id=\"post-title\" class=\"post-title\">\n              GRE বই ২০২৪: সেরা GRE প্রস্তুতির বইসমূহ\n            </h1>\n            <p class=\"post-meta\">\n              <span class=\"clock\" aria-hidden=\"true\">⏱️</span>\n              আপডেট করা হয়েছে: আগস্ট ৩০, ২০২৪\n            </p>\n          </header>\n\n          <section class=\"post-body\">\n            <p>\n              GRE পরীক্ষার প্রস্তুতি নিচ্ছেন? সঠিক বই নির্বাচন না করলে তা অনেক বড় পার্থক্য তৈরি করতে পারে।\n              এই বইগুলো আপনাকে পরীক্ষায় কাঙ্ক্ষিত স্কোরে পৌঁছাতে সাহায্য করবে এবং আপনার স্কোর উন্নত করতে সহায়তা করবে।\n              GRE বিশেষভাবে বিদেশে পড়াশোনা করতে ইচ্ছুক শিক্ষার্থীদের জন্য গুরুত্বপূর্ণ।\n            </p>\n            <p>\n              আপনি এই বইগুলো অনলাইনে বা দোকান থেকে কিনতে পারেন। এই লেখায় আমরা ২০২৪ সালের GRE পরীক্ষার জন্য\n              সেরা প্রস্তুতিমূলক বইগুলো আলোচনা করবো। এই বইগুলো GRE–এর সব বিভাগকে আচ্ছাদিত করে এবং আপনার লক্ষ্য স্কোরে\n              পৌঁছাতে সাহায্য করে।\n            </p>\n          </section>\n        </article>\n\n        <!-- =============== CARD CONTAINER (এই পৃষ্ঠায়) =============== -->\n        <section class=\"onpage-left\" aria-labelledby=\"onpage-left-title\">\n          <h2 id=\"onpage-left-title\" class=\"onpage-left__title\">\n            এই পৃষ্ঠায় <span aria-hidden=\"true\">→</span>\n          </h2>\n\n          <!-- Rail: 2-up desktop / 1-up mobile -->\n          <div class=\"onpage-left__cards\" id=\"onpageLeftCards\">\n            <!-- Card 1 -->\n            <article class=\"p-card\" data-href=\"post-1.html\" tabindex=\"0\" aria-label=\"১. GRE ২০২৪-এর জন্য সেরা প্রস্তুতিমূলক বই\">\n              <img src=\"image-1.jpg\" alt=\"\">\n              <div class=\"p-card__body\">\n                <h3 class=\"p-card__title\">১. GRE ২০২৪-এর জন্য সেরা প্রস্তুতিমূলক বই</h3>\n                <p class=\"p-card__desc\">GRE পরীক্ষায় প্রস্তুতি দ্রুত করার জন্য সেরা বই খুঁজছেন?</p>\n              </div>\n              <div class=\"p-card__foot\">\n                <a class=\"chip\" href=\"post-1.html\">আরও পড়ুন <span class=\"caret\">▾</span></a>\n                <span class=\"rating\">৩/৬</span>\n              </div>\n            </article>\n\n            <!-- Card 2 -->\n            <article class=\"p-card\" data-href=\"post-2.html\" tabindex=\"0\" aria-label=\"২. GRE ২০২৪-এর সেরা প্রস্তুতির বই: বিভাগ অনুযায়ী তালিকা\">\n              <img src=\"image-2.jpg\" alt=\"\">\n              <div class=\"p-card__body\">\n                <h3 class=\"p-card__title\">২. GRE ২০২৪-এর সেরা প্রস্তুতির বই: বিভাগ অনুযায়ী তালিকা</h3>\n                <p class=\"p-card__desc\">২০২৪ সালে GRE পরীক্ষায় প্রস্তুতির জন্য সেরা বই খুঁজছেন?</p>\n              </div>\n              <div class=\"p-card__foot\">\n                <a class=\"chip\" href=\"#gre-sectioned-books\">আরও পড়ুন <span class=\"caret\">▾</span></a>\n                <span class=\"rating\">২/৬</span>\n              </div>\n            </article>\n\n            <!-- Card 3 -->\n            <article class=\"p-card\" data-href=\"post-3.html\" tabindex=\"0\" aria-label=\"৩. আপনার জন্য প্রস্তুতিমূলক বই কোনগুলো?\">\n              <img src=\"image-3.jpg\" alt=\"\">\n              <div class=\"p-card__body\">\n                <h3 class=\"p-card__title\">৩. আপনার জন্য প্রস্তুতিমূলক বই কোনগুলো?</h3>\n                <p class=\"p-card__desc\">সময় কম? ফোকাসড থাকুন—এই গাইডেই সঠিক বই।</p>\n              </div>\n              <div class=\"p-card__foot\">\n                <a class=\"chip\" href=\"post-3.html\">আরও পড়ুন <span class=\"caret\">▾</span></a>\n                <span class=\"rating\">৪/৬</span>\n              </div>\n            </article>\n\n            <!-- Card 4 (extra for testing arrows) -->\n            <article class=\"p-card\" data-href=\"post-4.html\" tabindex=\"0\" aria-label=\"৪. GRE শব্দভাণ্ডার গড়তে সেরা ১০ বই\">\n              <img src=\"image-4.jpg\" alt=\"\">\n              <div class=\"p-card__body\">\n                <h3 class=\"p-card__title\">৪. GRE শব্দভাণ্ডার গড়তে সেরা ১০ বই</h3>\n                <p class=\"p-card__desc\">ভোকাবুলারি শক্তিশালী করতে এই বইগুলো হাতে রাখুন।</p>\n              </div>\n              <div class=\"p-card__foot\">\n                <a class=\"chip\" href=\"post-4.html\">আরও পড়ুন <span class=\"caret\">▾</span></a>\n                <span class=\"rating\">৫/৬</span>\n              </div>\n            </article>\n          </div>\n\n          <!-- Arrows INSIDE the white container -->\n          <div class=\"onpage-left__nav\">\n            <button class=\"nav prev\" type=\"button\" aria-label=\"পূর্ববর্তী\">‹</button>\n            <button class=\"nav next\" type=\"button\" aria-label=\"পরবর্তী\">›</button>\n          </div>\n        </section>\n\n        <!-- ============== LONG LIST: #1 (same width as cards) ============== -->\n        <section class=\"gre-list\" id=\"gre-top-books\">\n          <h2 class=\"gre-list__title\">১. GRE ২০২৪-এর জন্য সেরা প্রস্তুতিমূলক বই</h2>\n\n          <p class=\"gre-list__lead\"><strong>GRE পরীক্ষার প্রস্তুতি উন্নত করতে সেরা বই খুঁজছেন?</strong></p>\n          <p>এখানে কিছু শীর্ষ পর্যায়ের বইগুলো যা আপনার পরীক্ষায় সফল হতে সাহায্য করবে:</p>\n\n          <ol class=\"gre-list__ol\">\n            <li>\n              <strong>The Official Guide to the GRE General Test by ETS</strong> — ETS-এর অফিসিয়াল গাইড। প্র্যাকটিস প্রশ্ন,\n              টেস্ট নেওয়ার টিপস এবং আসল GRE উপকরণ রয়েছে।\n            </li>\n            <li>\n              <strong>GRE Prep by Magoosh</strong> — ভিডিও লেসন, প্র্যাকটিস প্রশ্ন, বিশদ ব্যাখ্যা ও স্টাডি প্ল্যানসহ\n              একটি পূর্ণাঙ্গ রিসোর্স।\n            </li>\n            <li>\n              <strong>Barron’s GRE (Sharon Weiner Green & Ira K. Wolf)</strong> — বিস্তৃত রিভিউ, গ্রেডেড প্রশ্ন, কৌশল ও টিপস।\n            </li>\n            <li>\n              <strong>Kaplan’s GRE Prep Plus 2024</strong> — কৌশল, প্র্যাকটিস প্রশ্ন, ফুল-লেংথ টেস্ট।\n            </li>\n            <li>\n              <strong>Manhattan Prep’s 5 lb. Book of GRE Practice Problems</strong> — ১,৮০০+ প্র্যাকটিস প্রশ্ন; কোয়ান্ট, রিজনিং ও AWA কভার।\n            </li>\n          </ol>\n\n          <p class=\"gre-list__end\">\n            এই বইগুলো প্র্যাকটিস প্রশ্ন এবং দ্রুত স্টাডি প্ল্যান পর্যন্ত বিস্তৃত রিসোর্স সরবরাহ করে, যা আপনার পরীক্ষায় সফলতা নিশ্চিত করতে সহায়তা করবে।\n          </p>\n        </section>\n\n        <!-- ============== LONG LIST: #2 (sectioned by AWA/Quant/Verbal) ============== -->\n        <!-- BOTTOM: বিভাগ অনুযায়ী বইয়ের তালিকা — FULL CONTENT -->\n        <section class=\"gre-sections\" id=\"gre-sectioned-books\">\n            <h2 class=\"gre-sections__title\">\n                ২. GRE ২০২৪-এর জন্য সেরা প্রস্তুতিমূলক বই: বিভাগ অনুযায়ী তালিকা\n            </h2>\n\n            <p class=\"gre-sections__lead\"><strong>২০২৪ সালের GRE-এর প্রস্তুতির জন্য সেরা বই খুঁজছেন?</strong></p>\n            <p>\n                GRE পরীক্ষায় প্রস্তুতির জন্য সঠিক স্টাডি ম্যাটেরিয়াল অত্যন্ত গুরুত্বপূর্ণ। চলুন কিছু সেরা বইয়ের দিকে নজর দেই,\n                যা আপনার প্রস্তুতির প্রতিটি ধাপে গাইড করতে এবং সফলতার সম্ভাবনা বাড়াবে।\n            </p>\n\n            <!-- AWA -->\n            <h3 class=\"gre-sections__h3\">\n                GRE Analytical Writing Assessment (AWA) সেকশনের জন্য GRE প্রস্তুতি বই\n            </h3>\n            <p>\n                GRE-এর Analytical Writing Assessment (AWA) সেকশন আপনার লেখা দক্ষতা প্রমাণ করতে হয়। এই সেকশনে\n                সফল হতে আপনাকে এমন একটি বইয়ের প্রয়োজন, যা স্পষ্ট ও সংক্ষিপ্ত এসেসি লেখার প্রয়োজনীয়তা সরবরাহ করে।\n            </p>\n            <p>\n                AWA প্রস্তুতির জন্য সেরা বইগুলোর মধ্যে একটি হলো <strong>“GRE Analytical Writing: Solutions to the Real Essay Topics”</strong>\n                (Vibrant Publishers)। এতে <strong>৬০টি আসল AWA এসেসি প্রশ্ন</strong> এবং সম্পূর্ণ এসেসির উদাহরণ রয়েছে, যা GRE স্কেলে\n                <strong>৬.০ নম্বর</strong> পেয়েছে। এই বইটি আপনার চিন্তাভাবনা সাজানো, <em>brainstorming</em> করা, <strong>গ্রামার</strong> ও\n                <strong>ভোকাবুলারি</strong> উন্নত করার টিপসও দেয়। কিভাবে <strong>হাই-স্কোরিং</strong> এসেসি লিখতে হয় এবং AWA দক্ষতা\n                উন্নয়নযোগ্যতা বাড়ানো যায় তাও শেখায়।\n            </p>\n            <p class=\"gre-sections__sublead\">অন্যান্য জনপ্রিয় AWA প্রস্তুতি বইগুলো হলো:</p>\n            <ul class=\"gre-sections__ul\">\n                <li><strong>“Cracking the GRE Premium Edition with 6 Practice Tests, 2024”</strong> (The Princeton Review)</li>\n                <li><strong>“GRE Analytical Writing: Solutions to the Real Essay Topics – Book 2”</strong> (Vibrant Publishers)</li>\n            </ul>\n\n            <!-- Quant -->\n            <h3 class=\"gre-sections__h3\">\n                GRE Quantitative Reasoning সেকশনের জন্য GRE প্রস্তুতি বই\n            </h3>\n            <p>\n                GRE পরীক্ষার <strong>Quantitative Reasoning</strong> সেকশন হলো সবচেয়ে গুরুত্বপূর্ণ এবং স্কোরিং সেকশনগুলোর একটি। এই\n                সেকশনে ভালো করার জন্য বিভিন্ন ধরনের কনসেপ্ট বুঝতে এবং <strong>নিয়মিত প্র্যাকটিস</strong> করতে হয়। এমন একটি বই প্রয়োজন,\n                যা GRE-এর সব টপিক কভার করে এবং প্রচুর প্র্যাকটিস প্রশ্ন সরবরাহ করে।\n            </p>\n            <p>\n                Quantitative Reasoning-এর জন্য সেরা বইগুলোর মধ্যে একটি হলো <strong>“5 lb. Book of GRE Practice Problems”</strong> by\n                Manhattan Prep। এতে GRE-এর সব কোয়ান্টিটেটিভ টপিকের ওপর <strong>২,০০০-এরও বেশি প্র্যাকটিস সমস্যা</strong> রয়েছে। প্রতিটি\n                সমস্যার জন্য বিস্তারিত ব্যাখ্যা এবং দ্রুত ও সঠিকভাবে সমাধান করার <em>strategy</em> প্রদান করা হয়েছে।\n            </p>\n            <p>\n                আরেকটি চমৎকার রিসোর্স হলো <strong>“GRE Math Workbook”</strong> by Kaplan। এতে শত শত প্র্যাকটিস প্রশ্ন, কুইজ,\n                বিস্তারিত ব্যাখ্যা এবং সমস্যা সমাধানের স্ট্র্যাটেজি রয়েছে। এগুলো একটি অগ্রগতিমূলক স্টাডি প্ল্যান তৈরি করতে\n                সাহায্য করে এবং আপনাকে গণনায় ফোকাস করতে সহায়তা করে।\n            </p>\n            <p>\n                আপনি চাইলে <strong>“5 lb. Book of GRE Practice Problems”</strong> বা <strong>“GRE Math Workbook”</strong>—যেকোনো একটি\n                নিতে পারেন। সঠিক বই এবং নিয়মিত প্র্যাকটিস আপনাকে Quantitative Reasoning দক্ষতা উন্নত করতে এবং GRE-এ আপনার লক্ষ্য\n                স্কোর অর্জনে সাহায্য করবে।\n            </p>\n\n            <!-- Verbal -->\n            <h3 class=\"gre-sections__h3\">\n                GRE Verbal Reasoning সেকশনের জন্য GRE প্রস্তুতি বই\n            </h3>\n            <p>\n                GRE পরীক্ষার <strong>Verbal Reasoning</strong> সেকশন আপনার লিখিত বিষয়বস্তুর বোধগম্যতা, বিশ্লেষণ ক্ষমতা এবং শব্দ ও ধারণার\n                মধ্যে সম্পর্ক বোঝার সক্ষমতা পরীক্ষা করে। এই সেকশনে সফল হতে হলে এমন একটি বই প্রয়োজন যা GRE-এর সব Verbal\n                Reasoning টপিক কভার করে এবং প্রচুর প্র্যাকটিস প্রশ্ন সরবরাহ করে, যাতে আপনার দক্ষতা দ্রুত বৃদ্ধি পায়।\n            </p>\n            <p>\n                Verbal Reasoning-এর জন্য সেরা বইগুলোর মধ্যে একটি হলো <strong>“The Official Guide to the GRE General Test”</strong> by ETS।\n                এই বইয়ে শত শত প্র্যাকটিস প্রশ্ন, ব্যাখ্যা, টিপস এবং স্ট্র্যাটেজি রয়েছে, যা Verbal Reasoning সেকশনে আপনার\n                পারফরম্যান্স উন্নত করতে সাহায্য করে।\n            </p>\n            <p>\n                আরেকটি জনপ্রিয় বই হলো <strong>“GRE Prep by Magoosh”</strong>। এই বই GRE-এর সব Verbal Reasoning টপিককে বিশদভাবে\n                রিভিউ, প্র্যাকটিস প্রশ্ন এবং ব্যাখ্যা প্রদান করে। এছাড়াও, এটি ভোকাবুলারি ও রিডিং কমপ্রিহেনশন উন্নত করার টিপস এবং\n                স্ট্র্যাটেজিও অন্তর্ভুক্ত করে।\n            </p>\n            <p>\n                আপনি আরও প্র্যাকটিস চাইলে <strong>“Barron’s GRE”</strong> by Sharon Weiner Green & Ira K. Wolf বিবেচনা করতে পারেন।\n                এই বইয়ে প্রচুর প্র্যাকটিস সেট ও কুইজ, বিস্তারিত ব্যাখ্যা এবং প্রত্যেক ধরনের Verbal Reasoning সমস্যার সমাধানের\n                স্ট্র্যাটেজি রয়েছে।\n            </p>\n            <p>\n                আপনি চাইলে <strong>“The Official Guide to the GRE General Test”</strong>, <strong>“GRE Prep by Magoosh”</strong>, বা\n                <strong>“Barron’s GRE”</strong>—যেকোনো একটি থেকে শুরু করতে পারেন। সঠিক বই এবং নিয়মিত প্র্যাকটিস আপনার Verbal Reasoning\n                দক্ষতা বাড়াতে এবং GRE-এ লক্ষ্য স্কোর অর্জনে সাহায্য করবে।\n            </p>\n        </section>\n\n\n        <section class=\"gre-choose\" id=\"gre-choose-books\">\n            <h2 class=\"gre-choose__title\">\n                ৩. আপনার জন্য সেরা GRE প্রস্তুতিমূলক বই কিভাবে নির্বাচন করবেন?\n            </h2>\n\n            <p class=\"gre-choose__lead\">\n                আপনার জন্য সেরা GRE প্রস্তুতিমূলক বই নির্বাচন করা একটি গুরুত্বপূর্ণ হতে পারে, কারণ প্রতিটি বিষয়ের গুরুত্ব\n                আলাদা। আপনার লক্ষ্য অনুযায়ী সঠিক GRE প্রস্তুতিমূলক বই বাছাই করার সময় নিচের বিষয়গুলো বিবেচনা করুন:\n            </p>\n\n            <ul class=\"gre-choose__ul\">\n                <li><span class=\"bn-count\">১.</span> <strong>বিষয়ভিত্তিক:</strong> এমন বই বেছে নিন যা GRE-এর সব বিভাগ কভার করে,\n                যেমন <em>Analytical Writing</em>, <em>Verbal Reasoning</em>, এবং <em>Quantitative Reasoning</em>। নিশ্চিত করুন বইটি\n                পরীক্ষায় আসতে পারে এমন বিষয়বস্তুকে সম্পূর্ণতার কাছাকাছি কভার করে।</li>\n\n                <li><span class=\"bn-count\">২.</span> <strong>প্র্যাকটিস প্রশ্ন:</strong> বহুমাত্রিক প্র্যাকটিস প্রশ্নসহ বইকে অগ্রাধিকার দিন—\n                যেখানে আসল ধাঁচের প্রশ্ন, ব্যাখ্যা ও স্কোরিং গাইড থাকে।</li>\n\n                <li><span class=\"bn-count\">৩.</span> <strong>রিভিউ ও রেটিং:</strong> যাচাইকৃত প্ল্যাটফর্মের রিভিউ/রেটিং এবং\n                শিক্ষার্থীদের মতামত দেখুন; বইটি সহজপাঠ্য ও ধারাবাহিক প্রগ্রেস গাইড করে কি না খেয়াল করুন।</li>\n\n                <li><span class=\"bn-count\">৪.</span> <strong>স্টাডি প্ল্যান:</strong> বেশিরভাগ বইয়ের ভিতরে থাকা স্টাডি প্ল্যান আছে কি না,\n                এবং আপনার সময়সূচির সাথে মানিয়ে নিতে পারে কি না—তা গুরুত্বপূর্ণ।</li>\n\n                <li><span class=\"bn-count\">৫.</span> <strong>ডিজিটাল সাপোর্ট:</strong> ভিডিও লেসন, অনলাইন কুইজ বা অ্যাপ সাপোর্ট থাকলে\n                তা বাড়তি সুবিধা দেয়; উচ্চ কোয়ালিটির ডিজিটাল কন্টেন্টসহ বইকে অগ্রাধিকার দিন।</li>\n            </ul>\n        </section>\n\n<!-- পরবর্তী ধাপ -->\n        <section class=\"next-steps\" aria-labelledby=\"next-steps-title\">\n            <h3 id=\"next-steps-title\" class=\"next-steps__title\">পরবর্তী ধাপ</h3>\n\n            <div class=\"steps-grid\">\n                <article class=\"step-card\">\n                <h4 class=\"step-card__title\">GRE পরীক্ষা</h4>\n                <a class=\"next-btn\" href=\"#!\">এখনই পড়ুন <span class=\"arr\">→</span></a>\n                </article>\n\n                <article class=\"step-card\">\n                <h4 class=\"step-card__title\">GRE পরীক্ষার ক্যালেন্ডার</h4>\n                <a class=\"next-btn\" href=\"#!\">এখনই পড়ুন <span class=\"arr\">→</span></a>\n                </article>\n\n                <article class=\"step-card\">\n                <h4 class=\"step-card__title\">GRE পরীক্ষার তারিখসমূহ</h4>\n                <a class=\"next-btn\" href=\"#!\">এখনই পড়ুন <span class=\"arr\">→</span></a>\n                </article>\n            </div>\n        </section>\n\n\n        <!-- ===== Info Banks: IELTS & GRE ===== -->\n        <section class=\"info-bank\">\n            <h3 class=\"info-title\">IELTS গুরুত্বপূর্ণ তথ্য</h3>\n\n            <!-- 4-column grid on desktop, 2 on tablets, 1 on phones -->\n            <div class=\"info-grid info-grid--ielts\" role=\"list\">\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">IELTS পরীক্ষা <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">IELTS পরীক্ষার তারিখ <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">IELTS পরীক্ষা ফি <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">IELTS কী <span class=\"chev\">→</span></a>\n\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">IELTS ফলাফল <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">IELTS পেপার বনাম অনলাইন পরীক্ষা <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">IELTS কথা বলা অনুশীলন পরীক্ষা <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">IELTS পরীক্ষার কেন্দ্র <span class=\"chev\">→</span></a>\n\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">IELTS স্কলারশিপ <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">IELTS-এর ধরন <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">IELTS প্যাটার্ন <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">IELTS ব্যান্ড স্কোর <span class=\"chev\">→</span></a>\n\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">IELTS পরীক্ষার যোগ্যতা <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">IELTS স্কোর বৃদ্ধি <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">IELTS রেজিস্ট্রেশন <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">IELTS প্রস্তুতি <span class=\"chev\">→</span></a>\n\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">IELTS বই <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">IELTS অনলাইন পরীক্ষা <span class=\"chev\">→</span></a>\n            </div>\n            </section>\n\n            <section class=\"info-bank\">\n            <h3 class=\"info-title\">GRE গুরুত্বপূর্ণ তথ্য</h3>\n\n            <!-- 3-column grid on desktop, 2 on tablets, 1 on phones -->\n            <div class=\"info-grid info-grid--gre\" role=\"list\">\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">GRE পরীক্ষা <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">GRE তারিখসমূহ <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">GRE ফলাফল <span class=\"chev\">→</span></a>\n\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">GRE ফি <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">GRE সিলেবাস <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">GRE বই <span class=\"chev\">→</span></a>\n\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">GRE রেজিস্ট্রেশন <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">GRE স্কোর বৃদ্ধি <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">GRE অনুশীলন <span class=\"chev\">→</span></a>\n\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">GRE প্রস্তুতি <span class=\"chev\">→</span></a>\n                <a class=\"info-link\" href=\"#\" role=\"listitem\">GRE অনলাইন পরীক্ষা <span class=\"chev\">→</span></a>\n            </div>\n        </section>\n\n        <!-- ===== FAQ: শিক্ষার্থীদের করা সবচেয়ে বেশি প্রশ্ন সমূহ ===== -->\n        <section class=\"faq\" id=\"gre-faq\">\n            <h3 class=\"faq__title\">শিক্ষার্থীদের করা সবচেয়ে বেশি প্রশ্ন সমূহ–</h3>\n\n            <div class=\"faq__list\">\n                <!-- Q1 -->\n                <details class=\"faq__item\">\n                <summary class=\"faq__q\">আমি GRE-এর জন্য কীভাবে প্রস্তুতি নেব?</summary>\n                <div class=\"faq__a\">\n                    <p>\n                    প্রথমে একটি <strong>ডায়াগনস্টিক মক</strong> দিন—এতে আপনার বর্তমান লেভেল, শক্তি-দুর্বলতা বোঝা যাবে।\n                    এরপর ৮–১২ সপ্তাহের একটি <strong>স্টাডি প্ল্যান</strong> বানান:\n                    </p>\n                    <ul>\n                    <li>প্রতিদিন ১–২ ঘন্টা কনসেপ্ট + ১ ঘন্টা প্র্যাকটিস (সপ্তাহে ১ দিন রিভিশন/রেস্ট)।</li>\n                    <li><strong>ম্যাটেরিয়াল:</strong> ETS Official Guide, Manhattan 5lb, Magoosh/Princeton Review।</li>\n                    <li><strong>Verbal:</strong> রিডিং প্র্যাকটিস, টেক্সট কমপ্লিশন/সেন্টেন্স ইকুইভ্যালেন্স; প্রতিদিন ভোকাবুলারি।</li>\n                    <li><strong>Quant:</strong> অ্যালজেব্রা, অ্যারিথমেটিক, জিওমেট্রি, ডাটা অ্যানালিসিস—ভুল প্রশ্ন নোট করুন।</li>\n                    <li><strong>AWA:</strong> সাম্প্রতিক টপিক থেকে ২–৩টি ইস্যু এসেসি লিখে ফিডব্যাক নিন।</li>\n                    <li>শেষ ২–৩ সপ্তাহে <strong>পূর্ণদৈর্ঘ্য মক</strong> দিয়ে টাইমিং/স্ট্যামিনা ঠিক করুন ও বিশ্লেষণ করে দুর্বলতা কাটান।</li>\n                    </ul>\n                </div>\n                </details>\n\n                <!-- Q2 -->\n                <details class=\"faq__item\">\n                <summary class=\"faq__q\">GRE-এর জন্য আমি কীভাবে রেজিস্ট্রেশন করব?</summary>\n                <div class=\"faq__a\">\n                    <ol>\n                    <li><strong>ETS অ্যাকাউন্ট</strong> খুলুন (ets.org) এবং প্রোফাইলে পাসপোর্টের নাম/তথ্য হুবহু দিন।</li>\n                    <li><strong>General Test</strong> নির্বাচন করে <em>Test Center</em> বা <em>GRE at Home</em> বেছে নিন।</li>\n                    <li>পছন্দের <strong>তারিখ/স্লট</strong> নির্বাচন করুন এবং ফি পরিশোধ করুন (অঞ্চলভেদে ভিন্ন হতে পারে)।</li>\n                    <li>কনফার্মেশন ইমেইল/অ্যাপয়েন্টমেন্ট প্রিন্ট রাখুন; রিশিডিউল/ক্যানসেল ডেডলাইন নজরে রাখুন।</li>\n                    <li>পরীক্ষার দিনে বৈধ <strong>পাসপোর্ট</strong> ও কনফার্মেশন সঙ্গে নিন।</li>\n                    </ol>\n                </div>\n                </details>\n\n                <!-- Q3 -->\n                <details class=\"faq__item\">\n                <summary class=\"faq__q\">GRE-এর সিলেবাস কী?</summary>\n                <div class=\"faq__a\">\n                    <p>\n                    <strong>Verbal Reasoning:</strong> Reading Comprehension, Text Completion, Sentence Equivalence।<br>\n                    <strong>Quantitative Reasoning:</strong> Arithmetic, Algebra, Geometry, Data Analysis (চার্ট/টেবিল, পরিসংখ্যান)।<br>\n                    <strong>Analytical Writing (AWA):</strong> বর্তমান ফর্ম্যাটে একটিমাত্র <em>Analyze an Issue</em> এসেসি (৩০ মিনিট)।\n                    </p>\n                    <p>পরীক্ষাটি সংক্ষিপ্তকরণ-পরবর্তী ভার্সনে মোট সময় ~২ ঘণ্টার কম; তবে টাইমিং/ব্লকিং দেশভেদে সামান্য বদলাতে পারে।</p>\n                </div>\n                </details>\n\n                <!-- Q4 -->\n                <details class=\"faq__item\">\n                <summary class=\"faq__q\">GRE-এর কোন অংশ সবচেয়ে গুরুত্বপূর্ণ?</summary>\n                <div class=\"faq__a\">\n                    <p>\n                    আপনার টার্গেট প্রোগ্রামের ওপর নির্ভর করে—<strong>STEM</strong> বা বিজনেস-স্কুলে সাধারণত <strong>Quant</strong> বেশি ওজন পায়,\n                    আর <strong>Humanities/Policy/LAW</strong> টাইপ প্রোগ্রামে <strong>Verbal</strong> ও <strong>AWA</strong> গুরুত্বপূর্ণ।\n                    তবু সামগ্রিকভাবে দু’টো রিজনিং সেকশনেই ভালো পারফরম্যান্স দরকার।\n                    </p>\n                </div>\n                </details>\n\n                <!-- Q5 -->\n                <details class=\"faq__item\">\n                <summary class=\"faq__q\">পরীক্ষার কাটঅফ কী রকম?</summary>\n                <div class=\"faq__a\">\n                    <p>\n                    GRE-এর কোনো <strong>অফিশিয়াল কাটঅফ</strong> নেই—বিশ্ববিদ্যালয়/ডিপার্টমেন্ট আলাদা বেঞ্চমার্ক ধরে।\n                    সাধারণ ধারণা হিসেবে:\n                    </p>\n                    <ul>\n                    <li>টপ-টিয়ার STEM: Quant <strong>165+</strong>, Verbal <strong>155+</strong> হলে প্রতিযোগিতামূলক ধরা যায়।</li>\n                    <li>অন্যান্য অনেক প্রোগ্রাম: Quant/Verbal <strong>150–155</strong> রেঞ্জকে গ্রহণযোগ্য ধরা হয়।</li>\n                    <li>শুধু স্কোর নয়—<strong>GPA, SOP, LOR, অভিজ্ঞতা</strong> ইত্যাদিও বড় ভূমিকা রাখে।</li>\n                    </ul>\n                    <p>ইনস্টিটিউট-সংশ্লিষ্ট পৃষ্ঠায় সদ্যতম রেঞ্জ দেখে নিন—এটাই সবচেয়ে নির্ভুল।</p>\n                </div>\n                </details>\n            </div>\n        </section>\n\n\n\n\n\n      </div>\n      <!-- ================= RIGHT SIDEBAR ================= -->\n      <aside class=\"sidebar\" aria-labelledby=\"more-title\">\n        <div class=\"side-head\">\n          <h2 id=\"more-title\">আরও পড়ুন</h2>\n          <a class=\"see-all\" href=\"#\">সব দেখুন</a>\n        </div>\n        <div class=\"side-list\">\n          <a class=\"side-item\" href=\"#\"><img src=\"image-1.jpg\" alt=\"\"><div class=\"side-txt\"><h3 class=\"side-title\">প্রযুক্তি শিক্ষার জন্য সেরা বিশ্ববিদ্যালয়গুলো</h3><p class=\"side-meta\">১২ জুলাই, ২০২৪ • ৫ মিনিট</p></div></a>\n          <a class=\"side-item\" href=\"#\"><img src=\"image-2.jpg\" alt=\"\"><div class=\"side-txt\"><h3 class=\"side-title\">বিশ্বের শীর্ষ ১০ বিশ্ববিদ্যালয়: কোথায় পড়বেন এবং কেন?</h3><p class=\"side-meta\">১৯ জুলাই, ২০২৪ • ৫ মিনিট</p></div></a>\n          <a class=\"side-item\" href=\"#\"><img src=\"image-3.jpg\" alt=\"\"><div class=\"side-txt\"><h3 class=\"side-title\">প্রযুক্তি শিক্ষার জন্য সেরা বিশ্ববিদ্যালয়গুলো</h3><p class=\"side-meta\">১৯ জুলাই, ২০২৪ • ৫ মিনিট</p></div></a>\n        </div>\n      </aside>\n    </div>\n  </main>\n\n  <script src=\"script.js\" defer></script>\n</body>\n</html>\n";

// Inject CSS
const style = document.createElement('style');
style.textContent = "/* ===== Palette ===== */\n:root{\n  --page: #EDE6FF;         /* soft lavender page bg */\n  --card: #FFFFFF;         /* white */\n  --ink: #131126;\n  --muted: #6F6A84;\n  --primary: #5B50E6;\n  --border: #E3DEF7;\n\n  --shadow: 0 10px 28px rgba(91,80,230,.10);\n  --maxw: 1180px;\n  --px: clamp(16px, 4vw, 28px);\n}\n\n*{ box-sizing: border-box; }\nhtml,body{ height:100%; }\n\n/* NEW: nice anchor scrolling */\nhtml{ scroll-behavior:smooth; }\n\nbody{\n  margin:0;\n  font-family:\"Noto Sans Bengali\",system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;\n  background:var(--page);\n  color:var(--ink);\n  -webkit-font-smoothing:antialiased;\n  text-rendering:optimizeLegibility;\n}\n\n.wrap{\n  width:min(100%,var(--maxw));\n  margin-inline:auto;\n  padding-inline:var(--px);\n  padding-block:28px 80px;\n}\n\n/* ================== Two-column Layout ================== */\n.grid{\n  display:grid;\n  gap:22px;\n  grid-template-columns:1fr;              /* mobile first */\n  align-items:start;\n}\n@media (min-width:1024px){\n  .grid{ grid-template-columns:1.12fr .64fr; }   /* left : right */\n}\n\n/* Left wrapper so sections stack under article */\n.grid-left{\n  display:flex; flex-direction:column; gap:22px; min-width:0;\n}\n.grid-left>*{ width:100%; }\n\n/* ================== Article ================== */\n.article-card{\n  background:var(--card);\n  border:1px solid var(--border);\n  border-radius:18px;\n  box-shadow:var(--shadow);\n  padding:clamp(16px,2.4vw,22px);\n}\n\n.crumbs{ font-size:14px; color:var(--muted); margin-bottom:8px; word-spacing:2px; }\n.crumbs a{ color:var(--muted); text-decoration:none; }\n.crumbs a:hover{ text-decoration:underline; }\n\n.post-title{\n  margin:4px 0 8px;\n  font-weight:800;\n  color:var(--primary);\n  font-size:clamp(26px,4.4vw,44px);\n  line-height:1.15;\n  letter-spacing:-.01em;\n}\n.post-meta{ display:flex; gap:8px; color:var(--muted); font-size:14px; margin:0 0 12px; }\n.post-body{ color:#241F3A; font-size:clamp(14px,1.8vw,16px); line-height:1.9; }\n.post-body p{ margin:0 0 14px; }\n\n/* ================== LEFT: 'এই পৃষ্ঠায়' (WHITE container, inside title + arrows) ================== */\n.onpage-left{\n  width:100%;\n  background:#fff;                       /* ← container is white */\n  border:1px solid var(--border);\n  border-radius:18px;\n  box-shadow:0 10px 28px rgba(91,80,230,.08);\n  padding:18px;\n}\n\n/* Title inside the white box */\n.onpage-left__title{\n  margin:0 0 12px 0;\n  font-weight:800;\n  color:var(--primary);\n  font-size:clamp(20px,2.8vw,28px);\n  display:flex; align-items:center; gap:8px;\n}\n\n/* Track: 2 cards per view (desktop), 1 per view (mobile) */\n.onpage-left__cards{\n  --gap:18px;\n  display:grid;\n  grid-auto-flow:column;\n  gap:var(--gap);\n  grid-auto-columns:calc((100% - var(--gap)) / 2);  /* 2-up */\n  overflow-x:auto;\n  scroll-snap-type:x mandatory;\n  -webkit-overflow-scrolling:touch;\n  scrollbar-width:none;\n}\n.onpage-left__cards::-webkit-scrollbar{ display:none; }\n@media (max-width:760px){\n  .onpage-left__cards{ grid-auto-columns:100%; }    /* 1-up */\n}\n.p-card{ scroll-snap-align:start; }\n\n/* Card */\n.p-card{\n  background:#fff;\n  border:1px solid var(--border);\n  border-radius:14px;\n  box-shadow:0 12px 28px rgba(91,80,230,.10);\n  display:flex; flex-direction:column; overflow:hidden;\n  cursor:pointer;\n  transition:transform .18s ease, box-shadow .25s ease;\n}\n.p-card:hover,.p-card:focus-within{\n  transform:translateY(-3px);\n  box-shadow:0 18px 40px rgba(91,80,230,.14);\n}\n.p-card:focus-visible{ outline:3px solid rgba(91,80,230,.35); outline-offset:2px; border-radius:16px; }\n\n.p-card img{\n  width:100%; height:176px; object-fit:cover; display:block;\n  transition:transform .28s cubic-bezier(.2,.7,.2,1);\n}\n.p-card:hover img,.p-card:focus-within img{ transform:scale(1.02); }\n\n/* Equal height + pinned footer */\n.p-card__body{ padding:12px 14px 0; flex:1; }\n.p-card__title{ margin:0 0 6px; font:800 16px/1.45 \"Noto Sans Bengali\",sans-serif; color:#201B39; }\n.p-card__desc{ margin:0; font-size:14px; line-height:1.6; color:#5b5871; }\n.p-card__foot{ display:flex; align-items:center; justify-content:space-between; padding:12px 14px 14px; gap:10px; }\n\n/* 'আরও পড়ুন' chip */\n.chip{\n  position:relative; overflow:hidden;\n  border:0; background:#F0EDFF; color:var(--primary);\n  font-weight:800; font-size:13px; border-radius:999px; padding:9px 12px;\n  transition:background-color .2s ease, transform .06s ease;\n}\n.caret{ margin-left:6px; transition:transform .2s ease; }\n.chip:hover .caret,.chip:focus-visible .caret{ transform:rotate(180deg); }\n.rating{ font-weight:800; font-size:12px; color:#4a3fd6; background:#FAF7FF; border-radius:10px; padding:6px 10px; }\n\n/* Arrows INSIDE the white container, aligned left under the track */\n.onpage-left__nav{\n  display:flex; gap:12px; margin:12px 0 0 0;\n}\n.nav{\n  width:52px; height:52px; border:0; border-radius:999px;\n  display:grid; place-items:center; background:var(--primary); color:#fff;\n  box-shadow:0 12px 28px rgba(91,80,230,.30); cursor:pointer;\n}\n.nav:active{ transform:translateY(1px); }\n\n/* ================== Sidebar ================== */\n.side-head{ display:flex; align-items:center; justify-content:space-between; padding:0 2px 8px; }\n.sidebar h2{ margin:0; font-weight:800; font-size:clamp(20px,2.6vw,28px); color:#17132E; letter-spacing:-.01em; }\n.see-all{ display:inline-flex; align-items:center; gap:6px; font-weight:800; font-size:14px; color:var(--primary); text-decoration:none; }\n.see-all:hover{ text-decoration:underline; }\n.side-list{ display:grid; gap:14px; }\n\n/* Invisible sidebar tiles (image + text only) */\n.side-item{ display:block; background:transparent; border:0; box-shadow:none; padding:0; text-decoration:none; color:inherit; }\n.side-item + .side-item{ margin-top:14px; }\n.side-item img{ width:100%; height:184px; object-fit:cover; border-radius:12px; display:block; }\n.side-txt{ padding:10px 2px 0; }\n.side-title{\n  margin:6px 0 6px; font-weight:800; font-size:16px; line-height:1.45; color:#211B3A;\n  display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden;\n}\n.side-meta{ margin:0; color:#776F92; font-size:13px; }\n\n/* ================== Reveal (used by JS) ================== */\n@media (prefers-reduced-motion: no-preference){\n  [data-reveal]{ opacity:0; transform:translateY(12px);\n    transition:opacity .5s cubic-bezier(.2,.7,.2,1), transform .5s cubic-bezier(.2,.7,.2,1);\n    transition-delay:var(--reveal-delay,0ms);\n  }\n  [data-reveal].is-visible{ opacity:1; transform:none; }\n\n  .side-item img{ transition:transform .18s ease; }\n  .side-item:hover img{ transform:translateY(-2px); }\n}\n\n\n/* --- Hover/Focus effect for 'আরও পড়ুন' button (chip) --- */\n.chip{\n  display:inline-flex; align-items:center; justify-content:center;\n  text-decoration:none;                  /* works for <a> and <button> */\n  background:#F0EDFF;                    /* default light lilac */\n  color:var(--primary);\n  border:0; border-radius:999px;\n  padding:9px 12px;\n  position:relative; overflow:hidden;\n  transition:\n    background-color .20s ease,\n    color .20s ease,\n    transform .12s ease,\n    box-shadow .20s ease;\n  box-shadow:0 0 0 rgba(0,0,0,0);\n}\n\n.chip .caret{ margin-left:6px; transition: transform .20s ease; }\n\n.chip:hover,\n.chip:focus-visible{\n  background:var(--primary);             /* fill on hover */\n  color:#fff;\n  transform:translateY(-1px);            /* tiny lift */\n  box-shadow:0 10px 24px rgba(91,80,230,.28);\n  cursor: pointer;\n}\n\n.chip:hover .caret,\n.chip:focus-visible .caret{\n  transform:rotate(180deg);\n}\n\n.chip:active{\n  transform:translateY(0);               /* settle on click */\n  box-shadow:0 6px 16px rgba(91,80,230,.22);\n  transition-duration:.06s;\n}\n\n/* nice keyboard outline */\n.chip:focus-visible{\n  outline:2px solid rgba(91,80,230,.45);\n  outline-offset:2px;\n}\n\n/* ==== GRE list block (bottom of card container) ==== */\n.gre-list{\n  background:#fff;\n  border:1px solid var(--border);\n  border-radius:18px;\n  box-shadow:0 10px 28px rgba(91,80,230,.08);\n  padding: clamp(16px, 2.4vw, 22px);\n}\n\n.gre-list__title{\n  margin:0 0 14px 0;\n  font-weight:800;\n  color:var(--primary);\n  font-size: clamp(22px, 3.6vw, 38px);\n  letter-spacing:-.01em;\n}\n\n.gre-list__lead{\n  margin:0 0 6px 0;\n  font-size: clamp(14px,1.8vw,16px);\n  color:#241F3A;\n}\n\n.gre-list__ol{\n  list-style:none;                 /* numbers are written in content */\n  padding-left:0;\n  margin: 10px 0 14px;\n}\n.gre-list__ol li{\n  margin: 10px 0 12px;\n  line-height:1.85;\n  color:#241F3A;\n  font-size: clamp(14px,1.8vw,16px);\n}\n.gre-list__ol li strong{\n  font-weight:700;\n  color:#141026;\n}\n\n.gre-list__end{\n  margin: 6px 0 0;\n  font-size: clamp(14px,1.8vw,16px);\n  line-height:1.85;\n  color:#241F3A;\n}\n\n.gre-sections{\n  background:#fff;\n  border:1px solid var(--border);\n  border-radius:18px;\n  box-shadow:0 10px 28px rgba(91,80,230,.08);\n  padding: clamp(16px, 2.6vw, 26px);\n}\n.gre-sections__title{\n  margin:0 0 16px;\n  font-weight:800;\n  color:var(--primary);\n  font-size: clamp(22px, 3.8vw, 40px);\n  line-height:1.2;\n  letter-spacing:-.01em;\n}\n.gre-sections__lead,\n.gre-sections p{\n  margin:0 0 12px;\n  font-size: clamp(14px,1.8vw,16px);\n  line-height:1.85;\n  color:#211B3A;\n}\n.gre-sections__h3{\n  margin:22px 0 10px;\n  font-weight:800;\n  color:var(--primary);\n  font-size: clamp(18px, 3.2vw, 30px);\n  line-height:1.25;\n}\n.gre-sections__ul{\n  margin:0 0 14px 18px;\n  padding-left:14px;\n}\n.gre-sections__ul li{\n  margin:6px 0;\n  line-height:1.85;\n  font-size: clamp(14px,1.8vw,16px);\n  color:#211B3A;\n}\n\n/* === ৩) কিভাবে বই নির্বাচন করবেন === */\n.gre-choose{\n  background:#fff;\n  border:1px solid var(--border);\n  border-radius:18px;\n  box-shadow:0 10px 28px rgba(91,80,230,.08);\n  padding:clamp(16px,2.6vw,26px);\n}\n.gre-choose__title{\n  margin:0 0 12px;\n  font-weight:800;\n  color:var(--primary);\n  font-size:clamp(20px,3.4vw,34px);\n  line-height:1.2;\n}\n.gre-choose__lead{\n  margin:0 0 10px;\n  font-size:clamp(14px,1.8vw,16px);\n  line-height:1.85;\n  color:#211B3A;\n}\n.gre-choose__ul{\n  list-style:none;\n  margin:6px 0 0;\n  padding:0;\n}\n.gre-choose__ul li{\n  position:relative;\n  padding-left:30px;\n  margin:10px 0;\n  line-height:1.85;\n  font-size:clamp(14px,1.8vw,16px);\n  color:#211B3A;\n}\n.gre-choose__ul .bn-count{\n  position:absolute; left:0; top:0;\n  color:var(--primary-700);\n  font-weight:800;\n}\n\n/* === পরবর্তী ধাপ (purple panel + 3 cards) === */\n.next-steps{\n  background:#F0EDFF;                 /* soft purple panel */\n  border:1px solid var(--border);\n  border-radius:18px;\n  padding:clamp(14px,2.2vw,20px);\n  box-shadow:0 8px 22px rgba(91,80,230,.08);\n}\n.next-steps__title{\n  margin:0 0 12px;\n  font-weight:800;\n  font-size:clamp(18px,2.8vw,24px);\n  color:var(--primary-700);\n}\n.steps-grid{\n  display:grid;\n  gap:16px;\n  grid-template-columns:repeat(3,1fr);\n}\n@media (max-width:860px){\n  .steps-grid{ grid-template-columns:1fr; }\n}\n.step-card{\n  background:#fff;\n  border:1px solid var(--border);\n  border-radius:14px;\n  box-shadow:var(--shadow);\n  padding:20px;\n  display:flex; flex-direction:column; gap:10px;\n}\n.step-card__title{\n  margin:0; color:#211B3A;\n  font-size:clamp(16px,2.3vw,18px);\n  font-weight:800;\n}\n.next-btn{\n  width:max-content;\n  display:inline-flex; align-items:center; gap:6px;\n  color:var(--primary);\n  font-weight:800; text-decoration:none;\n  padding:6px 2px; border-radius:8px;\n  transition:color .2s ease;\n}\n.next-btn .arr{ transition:transform .2s ease; }\n.next-btn:hover{ color:var(--primary-700); }\n.next-btn:hover .arr{ transform:translateX(4px); }\n\n/* keep buttons bottom aligned in every card */\n.steps-grid{ align-items:stretch; }\n.step-card{ display:flex; flex-direction:column; justify-content:flex-start; min-height:160px; padding:20px; }\n.step-card__title{ margin:0 0 10px 0; flex:0 0 auto; }\n.next-btn{ margin-top:auto; align-self:flex-start; white-space:nowrap; }\n\n/* ===== Info Bank panels (match next-steps styling) ===== */\n.info-bank{\n  background:#F0EDFF;                    /* soft purple panel */\n  border:1px solid var(--border);\n  border-radius:18px;\n  padding:clamp(14px,2.2vw,20px);\n  box-shadow:0 8px 22px rgba(91,80,230,.08);\n}\n.info-bank + .info-bank{ margin-top:18px; }   /* space between the two blocks */\n\n.info-title{\n  margin:0 0 12px;\n  font-weight:800;\n  font-size:clamp(18px,2.8vw,24px);\n  color:#2563EB;\n}\n\n/* white card that looks like a table */\n.info-grid{\n  background:#fff;\n  border:1px solid var(--border);\n  border-radius:12px;\n  overflow:hidden;             /* clip inner borders on radius */\n  display:grid;\n}\n\n.info-grid--ielts{ grid-template-columns:repeat(4,1fr); }\n.info-grid--gre{  grid-template-columns:repeat(3,1fr); }\n\n/* responsive columns */\n@media (max-width:1024px){\n  .info-grid--ielts{ grid-template-columns:repeat(3,1fr); }\n}\n@media (max-width:760px){\n  .info-grid--ielts{ grid-template-columns:repeat(2,1fr); }\n  .info-grid--gre{  grid-template-columns:repeat(2,1fr); }\n}\n@media (max-width:520px){\n  .info-grid--ielts,\n  .info-grid--gre{ grid-template-columns:1fr; }\n}\n\n/* cells */\n.info-link{\n  position:relative;\n  display:flex; align-items:center; justify-content:space-between;\n  gap:16px;\n  padding:14px 16px;\n  color:#201B39; text-decoration:none; font-weight:700;\n  line-height:1.45; background:#fff;\n  transition:background-color .15s ease;\n  border-top:1px solid var(--border);\n  border-left:1px solid var(--border);\n}\n\n/* add accent bar on hover */\n.info-link::before{\n  content:\"\";\n  position:absolute; left:0; top:0; bottom:0; width:0;\n  background:linear-gradient(180deg, rgba(91,80,230,.28), rgba(91,80,230,.18));\n  transition:width .22s ease;\n}\n.info-link:hover::before{ width:6px; }\n\n.info-grid > .info-link:nth-child(-n+4){ border-top:0; }           /* IELTS first row */\n.info-grid--gre  > .info-link:nth-child(-n+3){ border-top:0; }     /* GRE first row  */\n.info-grid > .info-link:nth-child(4n+1){ border-left:0; }          /* IELTS first col */\n.info-grid--gre  > .info-link:nth-child(3n+1){ border-left:0; }    /* GRE first col  */\n\n.info-link:hover{ background:#F7F5FF; }\n.chev{\n  flex:0 0 auto;\n  color:var(--primary);\n  font-weight:800;\n  transition:transform .2s ease;\n}\n.info-link:hover .chev{ transform:translateX(3px); }\n\n/* ===== FAQ (accordion) ===== */\n.faq{\n  background:#fff;\n  border:1px solid var(--border);\n  border-radius:18px;\n  box-shadow:0 10px 28px rgba(91,80,230,.08);\n  padding:clamp(14px,2.4vw,20px);\n}\n.faq__title{\n  margin:0 0 10px;\n  font-weight:800;\n  color:#2563EB;                 /* blue like your other titles */\n  font-size:clamp(18px,3vw,24px);\n}\n.faq__list{ border-top:1px solid var(--border); }\n\n.faq__item{ border-bottom:1px solid var(--border); }\n\n.faq__q{\n  list-style:none;               /* hide default marker */\n  cursor:pointer;\n  padding:14px 36px 14px 12px;\n  font-weight:700;\n  color:#201B39;\n  position:relative;\n}\n.faq__q::-webkit-details-marker{ display:none; }\n.faq__q::after{\n  content:\"▾\";\n  position:absolute;\n  right:10px; top:50%; transform:translateY(-50%);\n  color:#221F5B; font-weight:800;\n  transition:transform .2s ease;\n}\ndetails[open] > .faq__q::after{ transform:translateY(-50%) rotate(180deg); }\n\n.faq__a{\n  padding:0 12px 14px;\n  color:#211B3A;\n  font-size:clamp(14px,1.8vw,16px);\n  line-height:1.85;\n}\n.faq__a ul, .faq__a ol{ margin:8px 0 0 18px; }\n.faq__a li{ margin:6px 0; }\n\n/* ---------- ENHANCEMENTS: lighter titles + subtle interactions ---------- */\n\n/* 1) Make titles a bit lighter (700) */\n.post-title,\n.onpage-left__title,\n.p-card__title,\n.sidebar h2,\n.side-title,\n.gre-list__title,\n.gre-sections__title,\n.gre-sections__h3,\n.gre-choose__title,\n.next-steps__title,\n.step-card__title,\n.info-title,\n.faq__title{\n  font-weight:700 !important;\n}\n\n/* 2) Nav buttons: hover/press micro-interaction */\n.nav{\n  position:relative;\n  transition:transform .14s ease, box-shadow .22s ease;\n}\n.nav:hover{\n  transform:translateY(-2px);\n  box-shadow:0 16px 32px rgba(91,80,230,.36);\n}\n.nav.is-press{ transform:scale(.98); }\n\n/* 3) FAQ open -> fade-in */\n@media (prefers-reduced-motion: no-preference){\n  .faq__item[open] .faq__a{\n    animation:faqIn .22s ease;\n  }\n  @keyframes faqIn{\n    from{ opacity:0; transform:translateY(-4px); }\n    to{ opacity:1; transform:none; }\n  }\n}\n\n/* -------------------- SCROLL ANIMATIONS -------------------- */\n\n/* 1) Reveal variants (slide up / left / right / pop) */\n@media (prefers-reduced-motion: no-preference){\n  [data-reveal]{\n    opacity:0;\n    transform:translateY(16px);\n    filter:blur(6px);\n    transition:\n      opacity .6s cubic-bezier(.2,.7,.2,1),\n      transform .6s cubic-bezier(.2,.7,.2,1),\n      filter .6s cubic-bezier(.2,.7,.2,1);\n    transition-delay:var(--reveal-delay,0ms);\n    will-change:transform, opacity, filter;\n  }\n  [data-reveal].is-visible{\n    opacity:1; transform:none; filter:none;\n  }\n  .reveal-left[data-reveal]{ transform:translateX(-28px); }\n  .reveal-right[data-reveal]{ transform:translateX(28px); }\n  .reveal-pop[data-reveal]{ transform:scale(.96); }\n}\n\n/* 2) Scroll progress bar */\n.scroll-progress{\n  position:fixed; inset:0 auto auto 0; height:3px; width:0%;\n  background: linear-gradient(90deg,#5B50E6 0%, #8D84FF 100%);\n  box-shadow:0 1px 8px rgba(91,80,230,.35);\n  z-index:9999; pointer-events:none;\n}\n\n/* 3) Parallax blend with existing hover scale (uses CSS vars) */\n.p-card img{ transform: translateY(var(--parallax,0px)) scale(var(--scale,1)); }\n.p-card:hover img{ --scale:1.02; }\n.side-item img{ transform: translateY(var(--parallax,0px)) scale(var(--s,1)); }\n.side-item:hover img{ --s:1.02; }\n\n/* Keep headings INSIDE their cards during reveal */\n@media (prefers-reduced-motion: no-preference){\n  /* gentler offsets so text stays within padding */\n  .reveal-left[data-reveal]{  transform:translateX(-12px); }\n  .reveal-right[data-reveal]{ transform:translateX(12px); }\n  .reveal-pop[data-reveal]{   transform:scale(.985); } /* slightly subtler pop */\n}\n\n/* Clip any animation overspill so borders/padding never break */\n.article-card,\n.onpage-left,\n.gre-list,\n.gre-sections,\n.gre-choose,\n.next-steps,\n.info-bank,\n.faq{\n  overflow: hidden;         /* keep animated content inside the box */\n  contain: paint;           /* avoids paint bleeding during transforms */\n}\n\n/* In case a long title briefly causes horizontal overflow */\nhtml, body { overflow-x: hidden; }\n\n";
