// ------- Original JS logic (works in TS with DOM typings) -------
/* ===========================
   script.js — working arrows + UX polish
   =========================== */

const $  = (s, r=document) => r.querySelector(s);
const $$ = (s, r=document) => Array.from(r.querySelectorAll(s));
const REDUCED = matchMedia('(prefers-reduced-motion: reduce)').matches;

/* Subtle reveal on scroll */
function initReveal(){
  if (REDUCED) return;
  const targets = ['.article-card', '.sidebar .side-item', '.onpage-left .p-card'].flatMap(s => $$(s));
  targets.forEach((el, i) => {
    el.setAttribute('data-reveal', '');
    el.style.setProperty('--reveal-delay', `${Math.min(i*70, 480)}ms`);
  });
  const io = new IntersectionObserver((entries, obs) => {
    entries.forEach(e => { if (e.isIntersecting) { e.target.classList.add('is-visible'); obs.unobserve(e.target); } });
  }, { threshold: 0.18 });
  targets.forEach(el => io.observe(el));
}

/* Carousel logic (2-up desktop, 1-up mobile) */
function initOnpageCarousel(section){
  const rail = section.querySelector('#onpageLeftCards, .onpage-left__cards');
  const prev = section.querySelector('.prev');
  const next = section.querySelector('.next');
  if (!rail || !prev || !next) return;

  rail.style.scrollBehavior = 'smooth';

  const gap = () => parseFloat(getComputedStyle(rail).gap || '18');

  function step() {
    const card = rail.querySelector('.p-card');
    return (card ? card.getBoundingClientRect().width : rail.clientWidth) + gap();
  }

  function perView() {
    const s = step();
    return Math.max(1, Math.round(rail.clientWidth / s));
  }

  function maxIndex() {
    const total = rail.querySelectorAll('.p-card').length;
    return Math.max(0, total - perView());
  }

  function currIndex() {
    return Math.round(rail.scrollLeft / step());
  }

  function snapTo(idx) {
    const target = Math.max(0, Math.min(idx, maxIndex())) * step();
    rail.scrollTo({ left: target, behavior: 'smooth' });
  }

  prev.addEventListener('click', () => snapTo(currIndex() - 1));
  next.addEventListener('click', () => snapTo(currIndex() + 1));

  // keyboard support
  [prev, next].forEach(btn => btn.addEventListener('keydown', e => {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); btn.click(); }
  }));

  // make entire card clickable (anchor chips already work)
  $$('.p-card', rail).forEach(card => {
    const href = card.getAttribute('data-href');
    card.tabIndex = card.tabIndex || 0;
    card.addEventListener('click', e => {
      if (e.defaultPrevented) return;
      if (e.target.closest('.chip') || e.target.closest('.rating')) return;
      if (href) location.href = href;
    });
    card.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); if (href) location.href = href; }
    });
  });
}

/* Tiny press animation helper for buttons/links */
function initPressFX(){
  const pressables = [...$$('.nav'), ...$$('.chip'), ...$$('.next-btn')];
  pressables.forEach(el => {
    el.addEventListener('click', () => {
      el.classList.add('is-press');
      setTimeout(() => el.classList.remove('is-press'), 220);
    });
  });
}

/* Only one FAQ item open at a time */
function initFaqSingleOpen(){
  const faq = document.querySelector('#gre-faq .faq__list');
  if (!faq) return;
  faq.addEventListener('toggle', e => {
    if (e.target.tagName !== 'DETAILS' || !e.target.open) return;
    faq.querySelectorAll('details[open]').forEach(d => { if (d !== e.target) d.open = false; });
  }, true);
}

/* Init after DOM is ready */
document.addEventListener('DOMContentLoaded', () => {
  initReveal();
  $$('.onpage-left').forEach(initOnpageCarousel);
  initPressFX();
  initFaqSingleOpen();
});

/* -------------------- SCROLL ANIMATIONS -------------------- */

/* 1) Enhanced reveal-on-scroll: more targets + variant classes */
function initEnhancedReveal(){
  if (REDUCED) return;

  const groups = [
    // slide-up sections
    { sel: '.gre-list, .gre-sections, .gre-choose, .next-steps, .info-bank, .faq', klass: 'reveal-up' },
    // headings from left
    { sel: '.gre-sections__h3, .info-title, .next-steps__title, .faq__title', klass: 'reveal-left' },
    // pop-in cards / rows
    { sel: '.onpage-left .p-card, .steps-grid .step-card, .info-grid .info-link', klass: 'reveal-pop' },
    // article + sidebar already look great, still animate
    { sel: '.article-card, .sidebar .side-item', klass: 'reveal-up' },
  ];

  groups.forEach(({sel, klass}) => {
    $$(sel).forEach((el, i) => {
      el.setAttribute('data-reveal','');
      if (klass) el.classList.add(klass);
      el.style.setProperty('--reveal-delay', `${Math.min(i*70, 420)}ms`);
    });
  });

  // IO observer (reuses previous pattern if present)
  const io = new IntersectionObserver((entries, obs) => {
    entries.forEach(e => {
      if (e.isIntersecting){
        e.target.classList.add('is-visible');
        obs.unobserve(e.target);
      }
    });
  }, { threshold: 0.15 });

  $$('[data-reveal]').forEach(el => io.observe(el));
}

/* 2) Top scroll progress bar */
function initScrollProgress(){
  const bar = document.createElement('div');
  bar.className = 'scroll-progress';
  document.body.appendChild(bar);

  const update = () => {
    const max = document.documentElement.scrollHeight - innerHeight;
    const pct = max > 0 ? (scrollY / max) : 0;
    bar.style.width = (pct * 100).toFixed(2) + '%';
  };
  update();
  addEventListener('scroll', update, { passive: true });
  addEventListener('resize', update);
}

/* 3) Lightweight parallax on images (card + sidebar) */
function initParallax(){
  if (REDUCED) return;
  const imgs = $$('.p-card img, .side-item img');
  if (!imgs.length) return;

  const tick = () => {
    const vh = innerHeight;
    imgs.forEach(img => {
      const r = img.getBoundingClientRect();
      const center = r.top + r.height/2;
      const d = (center - vh/2) / vh;     // roughly -0.5..0.5
      const move = d * 12;                 // px
      img.style.setProperty('--parallax', `${move.toFixed(2)}px`);
    });
  };
  tick();
  addEventListener('scroll', tick, { passive: true });
  addEventListener('resize', tick);
}

/* Boot all the new goodies */
document.addEventListener('DOMContentLoaded', () => {
  initEnhancedReveal();
  initScrollProgress();
  initParallax();
});


// Ensure initializers run after DOM content injection if the original code relies on DOMContentLoaded
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    // no-op; original script.js already attaches its own DOMContentLoaded listeners
  });
}